<?php
require_once dirname(__DIR__,2).'/src/actions.php';require_method('POST');$u=current_user();$d=request_json();$key=$d['device_key']??'';$token=$d['fcm_token']??'';if(!is_string($key)||strlen($key)<8||strlen($key)>128||!is_string($token)||strlen($token)<16||strlen($token)>2048||!preg_match('/^[\x21-\x7E]+$/',$token))json_response(['error'=>['code'=>'invalid_device','message'=>'Invalid device key/token']],400);
mutate($u,$d,'device.register',function($pdo)use($u,$key,$token){$q=$pdo->prepare('UPDATE devices SET enabled=0 WHERE fcm_token=?');$q->execute([$token]);$q=$pdo->prepare('SELECT id FROM devices WHERE fcm_token=?');$q->execute([$token]);$id=$q->fetchColumn();if($id){$q=$pdo->prepare("UPDATE devices SET enabled=0,device_key=CONCAT('retired-',id) WHERE user_id=? AND device_key=? AND id<>?");$q->execute([$u['id'],$key,$id]);$q=$pdo->prepare('UPDATE devices SET user_id=?,device_key=?,enabled=1,updated_at=UTC_TIMESTAMP(6) WHERE id=?');$q->execute([$u['id'],$key,$id]);}else{$q=$pdo->prepare('INSERT INTO devices(id,user_id,device_key,fcm_token,updated_at) VALUES(?,?,?,?,UTC_TIMESTAMP(6)) ON DUPLICATE KEY UPDATE fcm_token=VALUES(fcm_token),enabled=1,updated_at=UTC_TIMESTAMP(6)');$q->execute([uuid_v4(),$u['id'],$key,$token]);}return ['ok'=>true];});
